{
  "name": "inbox-triage",
  "description": "Triages inbound messages - intake by webhook or a 15-minute poll, classify, draft replies in the owner's voice, human approval before anything sends, per-sender memory",
  "model": "openrouter/openai/gpt-4o-mini",
  "maxSteps": 15,
  "permissionMode": "default",
  "permissions": [
    { "tool": "delete_message", "action": "deny", "reason": "Triage never deletes mail - classify it 'spam' and mark it processed instead" },
    { "tool": "send_reply", "action": "ask", "reason": "Every outgoing reply is reviewed by a human before it is sent" },
    { "tool": ["list_messages", "read_message", "classify_message", "list_drafts", "draft_reply", "mark_processed", "remember_senders", "recall_senders"], "action": "allow" }
  ],
  "hooks": "hooks.ts",
  "compaction": { "thresholdPercent": 0.8 },
  "limits": { "maxCostUsd": 0.05 }
}

import type { ApproveToolCall } from '@lousho/build-ai-agent';
import { autoApproveSenders, findDraft, getMessage } from './lib/mailstore';

/**
 * An OPTIONAL standing-policy approver, deliberately NOT wired into
 * agent.json: the kit's contract is that a human reviews every send. With no
 * approver, the `ask` permission on `send_reply` pauses the run and the human
 * decides through `agent.approvals.resolve()`, a channel's
 * `/channels/<name>/approvals/:id` route, or the chat REPL's [y/N] prompt.
 *
 * A headless deployment that wants autonomy can add `"approve": "approve.ts"`
 * to agent.json. This approver then decides every pause: `send_reply` goes
 * out only to addresses or domains on the standing allowlist
 * (`data/auto-approve.json` or INBOX_TRIAGE_AUTO_APPROVE, comma-separated);
 * everything else is refused to the model, which reports "held for human
 * review" instead. An approver cannot abstain - whatever it returns IS the
 * decision - so wire it in only when that trade-off is intended.
 */

/** Who a send_reply would reach: the draft's recipient, else the original message's sender. */
async function recipientOf(args: Record<string, unknown>): Promise<string> {
  if (typeof args.draftId === 'string') {
    const draft = await findDraft(args.draftId);
    if (draft) return draft.to.toLowerCase();
  }
  if (typeof args.messageId === 'string') {
    try {
      return (await getMessage(args.messageId)).from.toLowerCase();
    } catch {
      return '';
    }
  }
  return '';
}

/** Whether `to` matches an allowlist entry (a full address or a '@domain' / bare domain). */
function allowlisted(to: string, entries: readonly string[]): boolean {
  return entries.some((entry) => {
    const normalized = entry.startsWith('@') ? entry.slice(1) : entry;
    return normalized.includes('@') ? to === normalized : to.endsWith(`@${normalized}`);
  });
}

const approve: ApproveToolCall = async ({ toolName, args }) => {
  if (toolName !== 'send_reply') return false;
  const to = await recipientOf(args);
  return to !== '' && allowlisted(to, await autoApproveSenders());
};

export default approve;

/**
 * The inbound channel (the kit's second intake, next to the poll schedule):
 * a webhook that accepts `POST /channels/inbound` with a JSON
 * `{ from, subject?, body }`, files the message into the kit's inbox store
 * and hands the agent a triage turn keyed to the sender - the sender is the
 * session key and the verified principal, so the 'senders' memory slot scopes
 * to whoever wrote in.
 *
 * Set INBOUND_TOKEN to require `Authorization: Bearer <token>`; unset, every
 * request is accepted (fine for a local demo, not for the public internet).
 * A paused turn replies 200 with the pending `approval`; decide it at
 * `POST /channels/inbound/approvals/<id>` like every channel.
 */
import { defineChannel } from '@lousho/build-ai-agent';
import { addMessage } from '../lib/mailstore';

export default defineChannel({
  name: 'inbound',
  async verify(req) {
    const expected = process.env.INBOUND_TOKEN;
    if (expected === undefined || expected === '') return true;
    return req.headers.authorization === `Bearer ${expected}`;
  },
  async parse(req) {
    const payload = JSON.parse(req.text || '{}') as { from?: unknown; subject?: unknown; body?: unknown };
    if (typeof payload.from !== 'string' || payload.from === '' || typeof payload.body !== 'string' || payload.body === '') {
      throw new SyntaxError("POST /channels/inbound wants a JSON body with 'from' and 'body' strings (optionally 'subject').");
    }
    const message = await addMessage({
      from: payload.from,
      subject: typeof payload.subject === 'string' && payload.subject !== '' ? payload.subject : '(no subject)',
      body: payload.body,
    });
    return {
      sessionKey: message.from,
      input:
        `A new message just arrived in the inbox: id ${message.id}, from ${message.from}, ` +
        `subject "${message.subject}". Triage it now: read_message, classify_message, ` +
        'recall what you know about the sender (recall_senders), draft_reply if it needs an answer ' +
        'and call send_reply once - it pauses for human review. mark_processed when done.',
      principal: { id: message.from, type: 'user', authenticator: 'inbound' },
      metadata: { sender: message.from },
      replyTo: null,
      event: { messageId: message.id },
    };
  },
  async reply({ inbound, sessionId, text, result, approval, respond }) {
    respond?.(200, { ok: true, sessionId, messageId: (inbound.event as { messageId?: string })?.messageId, text, finishReason: result?.finishReason, approval });
  },
});

import type { AgentHook } from '@lousho/build-ai-agent';
import { findDraft } from './lib/mailstore';

/**
 * The kit's hooks (pointed at by `agent.json`'s `hooks`):
 *
 * - loop-guard: denies a tool call the model already made twice with the same
 *   arguments (ported from coding-kit);
 * - output-cap: cuts long tool results so a fat newsletter can't flood the
 *   context;
 * - no-placeholder-send: triage-specific guardrail - refuses a `send_reply`
 *   whose effective body still contains a `[PLACEHOLDER]` before the approval
 *   pause even happens, so a human is never asked to approve half-finished
 *   mail.
 */

/**
 * Deny a tool call the model already made `maxRepeats` times with the same
 * arguments. `exempt` names approval-gated tools: `send_reply` pauses for a
 * human and its preToolCall fires again when the approved call resumes, so
 * counting it would let the guard overrule a human's explicit approval.
 */
export function loopGuard(maxRepeats = 2, exempt: readonly string[] = []): AgentHook {
  const seen = new Map<string, number>();
  const skip = new Set(exempt);
  return {
    name: 'loop-guard',
    preToolCall(ctx) {
      if (skip.has(ctx.toolName)) return undefined;
      const key = `${ctx.sessionId ?? ''}:${ctx.toolName}:${JSON.stringify(ctx.args)}`;
      const count = (seen.get(key) ?? 0) + 1;
      seen.set(key, count);
      if (count > maxRepeats) {
        return { deny: `You already called ${ctx.toolName} with these arguments ${maxRepeats} times. Try something else.` };
      }
      return undefined;
    },
  };
}

/** Cut long tool results so they do not flood the context. */
export function outputCap(maxChars = 4_000): AgentHook {
  return {
    name: 'output-cap',
    postToolCall(_ctx, result) {
      const text = typeof result.result === 'string' ? result.result : JSON.stringify(result.result ?? '');
      if (text.length <= maxChars) return undefined;
      return { result: `${text.slice(0, maxChars)}\n[output cut at ${maxChars} of ${text.length} chars]` };
    },
  };
}

/** The body a send_reply would actually send: the inline `body`, else the referenced draft's. */
async function outgoingBody(args: Record<string, unknown>): Promise<string> {
  if (typeof args.body === 'string') return args.body;
  if (typeof args.draftId === 'string') return (await findDraft(args.draftId))?.body ?? '';
  return '';
}

const PLACEHOLDER = /\[[A-Za-z][A-Za-z _-]{1,40}\]/;

/** Refuse a send whose body still has a [PLACEHOLDER] or is empty - before the approval pause. */
export function noPlaceholderSend(): AgentHook {
  return {
    name: 'no-placeholder-send',
    async preToolCall(ctx) {
      if (ctx.toolName !== 'send_reply') return undefined;
      const body = await outgoingBody(ctx.args);
      const placeholder = PLACEHOLDER.exec(body);
      if (body.trim() === '') {
        return { deny: 'send_reply has no body. Write the reply with draft_reply first, or pass a complete body.' };
      }
      if (placeholder) {
        return {
          deny: `The reply still contains the placeholder ${placeholder[0]}. Fill it in (or remove it) and ask again - a human should not be paged for half-finished mail.`,
        };
      }
      return undefined;
    },
  };
}

export default [loopGuard(2, ['send_reply']), noPlaceholderSend(), outputCap()];

/**
 * The inbox-triage kit, tested offline: `loadAgentDir()` reads the kit's own
 * directory and a scripted `mockModel` drives the triage loop - classify,
 * draft, pause on `send_reply`, deny (nothing leaves) and approve (the reply
 * lands in the outbox). The store is a temp dir via INBOX_TRIAGE_HOME so the
 * kit's seeded data/ stays untouched.
 *
 * The kit's files import `@lousho/build-ai-agent` by name, which resolves to
 * the workspace self-link (dist/) inside this repo - like
 * examples/coding-harness/kit.test.ts this needs `npm run build` to have run.
 */
import { afterAll, beforeEach, describe, expect, it, vi } from 'vitest';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import { loadAgentDir, resolveAgentDir, startSchedules } from '@lousho/build-ai-agent';
import type { ChannelContext, ChannelInbound, ChannelRequest } from '@lousho/build-ai-agent';
import { mockModel, type MockModel } from '@lousho/build-ai-agent/testing';

const KIT = __dirname;
const home = fs.mkdtempSync(path.join(os.tmpdir(), 'inbox-triage-'));
process.env.INBOX_TRIAGE_HOME = home;

const SEED = [
  { id: 'm-budget', from: 'priya@acme.com', subject: 'Invoice #1042 question', body: 'Hi - the invoice lists 12 seats but we only have 10. Confirm before Friday?', receivedAt: '2026-01-05T09:12:00.000Z', status: 'new' },
  { id: 'm-spam', from: 'winner@lottery-prizes.example', subject: 'You WON $5,000,000', body: 'Claim your prize now - reply with your bank details.', receivedAt: '2026-01-05T07:30:00.000Z', status: 'new' },
];

function resetHome() {
  fs.rmSync(home, { recursive: true, force: true });
  fs.mkdirSync(home, { recursive: true });
  fs.writeFileSync(path.join(home, 'inbox.json'), `${JSON.stringify(SEED, null, 2)}\n`, 'utf8');
}

interface JsonRecord {
  [key: string]: unknown;
}

function readJson(name: string): JsonRecord[] {
  return JSON.parse(fs.readFileSync(path.join(home, name), 'utf8')) as JsonRecord[];
}

const exists = (name: string): boolean => fs.existsSync(path.join(home, name));

const toolOutputs = (provider: MockModel): string =>
  provider.calls[provider.calls.length - 1].messages
    .filter((m) => m.role === 'tool')
    .map((m) => String(m.content))
    .join('\n');

const systemOf = (call: { messages: readonly { role: string; content: unknown }[] }): string =>
  String(call.messages.find((m) => m.role === 'system')?.content);

beforeEach(resetHome);
afterAll(() => fs.rmSync(home, { recursive: true, force: true }));

describe('the kit directory, resolved', () => {
  it('discovers tools, the poll schedule, the inbound channel and the senders memory', async () => {
    const { config, manifest, schedules, channels } = await resolveAgentDir(KIT, { provider: mockModel(['x']) });

    expect(manifest.name).toBe('inbox-triage');
    expect([...manifest.tools].sort()).toEqual(
      ['classify_message', 'delete_message', 'draft_reply', 'list_drafts', 'list_messages', 'mark_processed', 'read_message', 'send_reply'].sort()
    );
    expect(manifest.schedules).toEqual(['poll-inbox']);
    expect(manifest.channels).toEqual(['inbound']);
    expect(manifest.memory).toEqual(['senders']);
    expect(schedules[0].cron).toBe('*/15 * * * *');
    expect(schedules[0].prompt).toContain('list_messages');
    expect(channels[0].name).toBe('inbound');
    expect(manifest.files.some((file) => file.endsWith('hooks.ts'))).toBe(true);
  });

  it('appends instructions/openai.md when the model id names the openai family', async () => {
    const { config } = await resolveAgentDir(KIT, { provider: mockModel(['x']), model: 'openai/test-model' });
    expect(String(config.instructions)).toContain('one tool call at a time');
  });
});

describe('the loaded kit, offline', () => {
  it('classifies, drafts, pauses send_reply for the human and sends only on approval', async () => {
    const audit: string[] = [];
    const provider = mockModel([
      { toolCalls: [{ name: 'list_messages', args: { status: 'new' } }] },
      { toolCalls: [{ name: 'classify_message', args: { id: 'm-budget', category: 'reply-needed', reason: 'customer billing question' } }] },
      { toolCalls: [{ name: 'remember_senders', args: { text: 'priya@acme.com - billing contact at Acme, wants plain acknowledgements' } }] },
      { toolCalls: [{ name: 'draft_reply', args: { messageId: 'm-budget', body: 'Hi Priya - you are right, it is 10 seats. A corrected invoice goes out Friday.' } }] },
      { toolCalls: [{ name: 'send_reply', args: { messageId: 'm-budget', draftId: 'draft-m-budget-1' } }] },
      // the run continues after the denial
      { toolCalls: [{ name: 'mark_processed', args: { id: 'm-spam' } }] },
      { text: 'Held the reply to Priya for review; processed the spam message.' },
      // second run: the human approves
      { toolCalls: [{ name: 'send_reply', args: { messageId: 'm-budget', draftId: 'draft-m-budget-1' } }] },
      { text: 'Sent the corrected-invoice reply to Priya.' },
      // third run: recall surfaces the sender fact in the system prompt
      { text: 'Done.' },
    ]);
    const agent = await loadAgentDir(KIT, {
      provider,
      onPermissionDecision: (entry) => audit.push(`${entry.toolName}:${entry.decision}`),
    });

    const paused = await agent.send('Triage the inbox.');
    expect(paused.finishReason).toBe('awaiting-approval');
    expect(exists('outbox.json')).toBe(false); // nothing leaves before the human decides

    const denied = await agent.approvals.resolve({ id: paused.approvalId!, approved: false, note: 'Not yet' });
    expect(denied.finishReason).toBe('stop');
    expect(exists('outbox.json')).toBe(false);

    const drafts = readJson('drafts.json');
    expect(drafts).toHaveLength(1);
    expect(drafts[0]).toMatchObject({ id: 'draft-m-budget-1', messageId: 'm-budget', to: 'priya@acme.com', status: 'draft' });
    const message = readJson('inbox.json').find((m) => m.id === 'm-budget');
    expect(message).toMatchObject({ category: 'reply-needed', status: 'triaged' });
    expect(readJson('inbox.json').find((m) => m.id === 'm-spam')).toMatchObject({ status: 'processed' });
    expect(audit).toContain('send_reply:ask');

    // memory was written: senders slot, shared scope (no sender principal in a bare send)
    const memoryFile = path.join(home, 'memory', 'shared.json');
    expect(fs.existsSync(memoryFile)).toBe(true);
    expect(fs.readFileSync(memoryFile, 'utf8')).toContain('priya@acme.com');

    const pausedAgain = await agent.send('Send the pending reply.');
    expect(pausedAgain.finishReason).toBe('awaiting-approval');
    const done = await agent.approvals.resolve({ id: pausedAgain.approvalId!, approved: true });
    expect(done.text).toContain('Sent');

    const outbox = readJson('outbox.json');
    expect(outbox).toHaveLength(1);
    expect(outbox[0]).toMatchObject({ messageId: 'm-budget', draftId: 'draft-m-budget-1', to: 'priya@acme.com' });
    expect(String(outbox[0].body)).toContain('10 seats');
    expect(readJson('inbox.json').find((m) => m.id === 'm-budget')).toMatchObject({ status: 'replied' });
    expect(readJson('drafts.json')[0]).toMatchObject({ status: 'sent' });

    // the remembered sender fact is recalled into the next run's system prompt
    await agent.send('Anything new?');
    expect(systemOf(provider.calls[provider.calls.length - 1])).toContain('<memory name="senders">');
    expect(systemOf(provider.calls[provider.calls.length - 1])).toContain('priya@acme.com');
  }, 30_000);

  it('denies delete_message outright and refuses a send_reply with placeholders before the pause', async () => {
    const provider = mockModel([
      { toolCalls: [{ name: 'delete_message', args: { id: 'm-spam' } }] },
      { toolCalls: [{ name: 'send_reply', args: { messageId: 'm-budget', body: 'Hi [NAME], thanks for writing in.' } }] },
      { text: 'Deletion denied; the placeholder draft was refused too.' },
    ]);
    const agent = await loadAgentDir(KIT, { provider });

    const result = await agent.send('Delete the spam and reply to the invoice mail.');

    expect(result.finishReason).toBe('stop'); // no pause: deny rule + hook, not an approval
    expect(readJson('inbox.json').find((m) => m.id === 'm-spam')).toMatchObject({ status: 'new' });
    const outputs = toolOutputs(provider);
    expect(outputs).toContain('Triage never deletes');
    expect(outputs).toContain('[NAME]');
    expect(exists('outbox.json')).toBe(false);
  });
});

describe('intake', () => {
  it('poll-inbox fires its sweep prompt on the cron tick', async () => {
    const provider = mockModel([{ text: 'Nothing new.' }]);
    const agent = await loadAgentDir(KIT, { provider });
    const { schedules } = await resolveAgentDir(KIT, { provider });

    let now = Date.parse('2026-01-05T12:00:00Z');
    let fire: (() => void) | undefined;
    const running = startSchedules(agent, schedules, {
      now: () => now,
      setTimer: (fn) => {
        fire = fn;
        return () => {};
      },
    });
    try {
      expect(fire).toBeDefined();
      now += 15 * 60 * 1000; // past the next quarter-hour boundary
      fire!();
      await vi.waitFor(() => expect(provider.calls.length).toBe(1));
      const prompt = String(provider.calls[0].messages.at(-1)?.content);
      expect(prompt).toContain('list_messages');
      expect(prompt).toContain('classify_message');
    } finally {
      running.stop();
    }
  });

  it('the inbound channel files a posted message and hands the turn to the sender', async () => {
    const { channels } = await resolveAgentDir(KIT, { provider: mockModel(['x']) });
    const channel = channels[0];

    const body = JSON.stringify({ from: 'bob@corp.example', subject: 'Pricing?', body: 'What does the team plan cost?' });
    const req: ChannelRequest = { method: 'POST', url: '/channels/inbound', headers: {}, rawBody: new TextEncoder().encode(body), text: body };
    const ctx: ChannelContext = {
      approval: async () => undefined,
      sessionId: (key) => `inbound:${key}`,
      hasSession: async () => false,
      pendingQuestion: async () => undefined,
    };

    expect(await channel.verify?.(req)).toBe(true); // INBOUND_TOKEN unset: open intake
    const inbound = (await channel.parse(req, () => {}, ctx)) as ChannelInbound;
    expect(inbound.sessionKey).toBe('bob@corp.example');
    expect(inbound.metadata).toMatchObject({ sender: 'bob@corp.example' });
    expect(inbound.principal).toMatchObject({ id: 'bob@corp.example' });
    expect(String(inbound.input)).toContain('Pricing?');

    const message = readJson('inbox.json').find((m) => m.from === 'bob@corp.example');
    expect(message).toMatchObject({ subject: 'Pricing?', status: 'new' });

    let responded: unknown;
    await channel.reply({ inbound, sessionId: 's-1', text: 'triaged', respond: (_status, out) => (responded = out) });
    expect(responded).toMatchObject({ ok: true, messageId: message?.id });
  });
});

describe('live', () => {
  it.skipIf(!process.env.OPENROUTER_API_KEY)('triages the seeded inbox on the real model', async () => {
    const agent = await loadAgentDir(KIT);
    const result = await agent.send('Triage the inbox: classify everything new, draft a reply where one is needed.');
    // whatever it does, it must stop at a send for a human - or stop cleanly
    if (result.finishReason === 'awaiting-approval') {
      await agent.approvals.resolve({ id: result.approvalId!, approved: false, note: 'test: do not actually send' });
    }
    const inbox = readJson('inbox.json');
    expect(inbox.every((message) => message.status !== 'new')).toBe(true);
    expect(exists('outbox.json')).toBe(false);
  }, 120_000);
});

/**
 * The kit's backing store: a handful of JSON files in one directory so the
 * whole kit runs (and is inspectable) offline.
 *
 *   inbox.json           inbound messages and their triage state
 *   drafts.json          replies the agent wrote but nobody sent
 *   outbox.json          replies a human approved and send_reply recorded
 *   auto-approve.json    optional standing allowlist for approve.ts
 *   memory/              per-sender memory slot files (memory/senders.ts)
 *
 * The directory is `INBOX_TRIAGE_HOME` when set, else `data/` inside the
 * installed kit, so a deployment can point the store at a volume and tests
 * at a temp dir.
 */
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { randomUUID } from 'node:crypto';

export type MessageStatus = 'new' | 'triaged' | 'replied' | 'processed' | 'trashed';
export type MessageCategory = 'urgent' | 'reply-needed' | 'fyi' | 'spam';

export interface StoredMessage {
  id: string;
  from: string;
  subject: string;
  body: string;
  receivedAt: string;
  status: MessageStatus;
  category?: MessageCategory;
  categoryReason?: string;
}

export interface Draft {
  id: string;
  messageId: string;
  to: string;
  subject: string;
  body: string;
  createdAt: string;
  status: 'draft' | 'sent' | 'rejected';
}

export interface OutboxEntry {
  id: string;
  messageId: string;
  draftId?: string;
  to: string;
  subject: string;
  body: string;
  sentAt: string;
}

/** The store directory: `INBOX_TRIAGE_HOME` when set, else `<kit>/data`. */
export function home(): string {
  const env = process.env.INBOX_TRIAGE_HOME;
  if (env !== undefined && env.trim() !== '') return path.resolve(env);
  return path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', 'data');
}

function file(name: string): string {
  return path.join(home(), name);
}

async function readJson<T>(name: string, fallback: T): Promise<T> {
  try {
    return JSON.parse(await readFile(file(name), 'utf8')) as T;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return fallback;
    throw error;
  }
}

/** Writes atomically (temp file + rename) so a crashed run never leaves a torn JSON file. */
async function writeJson(name: string, value: unknown): Promise<void> {
  await mkdir(home(), { recursive: true });
  const temp = `${file(name)}.${randomUUID()}.tmp`;
  await writeFile(temp, `${JSON.stringify(value, null, 2)}\n`, 'utf8');
  await rename(temp, file(name));
}

export async function listMessages(status?: MessageStatus): Promise<StoredMessage[]> {
  const messages = await readJson<StoredMessage[]>('inbox.json', []);
  const filtered = status === undefined ? messages : messages.filter((message) => message.status === status);
  return filtered.slice().sort((a, b) => b.receivedAt.localeCompare(a.receivedAt));
}

export async function getMessage(id: string): Promise<StoredMessage> {
  const message = (await readJson<StoredMessage[]>('inbox.json', [])).find((candidate) => candidate.id === id);
  if (message === undefined) throw new Error(`no message with id '${id}' - call list_messages for the current ids`);
  return message;
}

export async function updateMessage(id: string, patch: Partial<StoredMessage>): Promise<StoredMessage> {
  const messages = await readJson<StoredMessage[]>('inbox.json', []);
  const index = messages.findIndex((candidate) => candidate.id === id);
  if (index === -1) throw new Error(`no message with id '${id}' - call list_messages for the current ids`);
  messages[index] = { ...messages[index], ...patch, id };
  await writeJson('inbox.json', messages);
  return messages[index];
}

/** Drops a new inbound message into the inbox (the channel's intake path). */
export async function addMessage(input: { from: string; subject: string; body: string }): Promise<StoredMessage> {
  const messages = await readJson<StoredMessage[]>('inbox.json', []);
  const message: StoredMessage = {
    id: `m-${randomUUID().slice(0, 8)}`,
    from: input.from,
    subject: input.subject,
    body: input.body,
    receivedAt: new Date().toISOString(),
    status: 'new',
  };
  messages.push(message);
  await writeJson('inbox.json', messages);
  return message;
}

export async function listDrafts(messageId?: string): Promise<Draft[]> {
  const drafts = await readJson<Draft[]>('drafts.json', []);
  return messageId === undefined ? drafts : drafts.filter((draft) => draft.messageId === messageId);
}

export async function findDraft(id: string): Promise<Draft | undefined> {
  return (await readJson<Draft[]>('drafts.json', [])).find((draft) => draft.id === id);
}

/**
 * Adds a draft for `messageId`. Ids are deterministic (`draft-<message>-<n>`)
 * so a follow-up call (and a script or test) can name the draft it just made.
 */
export async function addDraft(draft: Omit<Draft, 'id' | 'createdAt' | 'status'>): Promise<Draft> {
  const drafts = await readJson<Draft[]>('drafts.json', []);
  const count = drafts.filter((candidate) => candidate.messageId === draft.messageId).length;
  const created: Draft = { ...draft, id: `draft-${draft.messageId}-${count + 1}`, createdAt: new Date().toISOString(), status: 'draft' };
  drafts.push(created);
  await writeJson('drafts.json', drafts);
  return created;
}

export async function updateDraft(id: string, patch: Partial<Draft>): Promise<Draft> {
  const drafts = await readJson<Draft[]>('drafts.json', []);
  const index = drafts.findIndex((candidate) => candidate.id === id);
  if (index === -1) throw new Error(`no draft with id '${id}'`);
  drafts[index] = { ...drafts[index], ...patch, id };
  await writeJson('drafts.json', drafts);
  return drafts[index];
}

export async function readOutbox(): Promise<OutboxEntry[]> {
  return readJson<OutboxEntry[]>('outbox.json', []);
}

export async function appendOutbox(entry: Omit<OutboxEntry, 'id' | 'sentAt'>): Promise<OutboxEntry> {
  const outbox = await readOutbox();
  const sent: OutboxEntry = { ...entry, id: `out-${outbox.length + 1}`, sentAt: new Date().toISOString() };
  outbox.push(sent);
  await writeJson('outbox.json', outbox);
  return sent;
}

/**
 * The standing allowlist approve.ts uses when a deployment wires it in:
 * addresses and `@domain` entries from `auto-approve.json`, plus any
 * comma-separated entries in INBOX_TRIAGE_AUTO_APPROVE.
 */
export async function autoApproveSenders(): Promise<string[]> {
  const fromFile = await readJson<string[]>('auto-approve.json', []);
  const fromEnv = (process.env.INBOX_TRIAGE_AUTO_APPROVE ?? '')
    .split(',')
    .map((entry) => entry.trim().toLowerCase())
    .filter((entry) => entry !== '');
  return [...fromFile.map((entry) => entry.toLowerCase()), ...fromEnv];
}

/**
 * Per-sender memory ("remember per-sender facts"): who prefers a terse reply,
 * whose timezone is UTC+2, which alias the billing contact answers to.
 *
 * Scope: a run that acts for a verified sender (the inbound channel sets the
 * principal; callers can also pass `metadata.sender` to send()) gets that
 * sender's own file. Batch runs - the poll schedule, a bare `agent.send` -
 * share the 'shared' scope, so facts there are written per sender inside the
 * text ("priya@acme.com - prefers ...") and visible on every sweep.
 *
 * The provider wraps fileMemory() so `dir` is resolved on each call: the same
 * INBOX_TRIAGE_HOME the mail store uses, under `memory/`.
 */
import path from 'node:path';
import { defineMemory, fileMemory, type MemoryProvider } from '@lousho/build-ai-agent';
import { home } from '../lib/mailstore';

const backing = (): MemoryProvider => fileMemory({ dir: path.join(home(), 'memory') });

const provider: MemoryProvider = {
  list: (scopeKey, options) => backing().list(scopeKey, options),
  add: (scopeKey, item) => backing().add(scopeKey, item),
  remove: (scopeKey, id) => backing().remove(scopeKey, id),
};

export default defineMemory({
  name: 'senders',
  description:
    'Facts about the people who write in: how they like to be addressed, tone, time zone, role, past decisions. In shared-scope runs, start each item with the sender address.',
  scope: (ctx) => {
    const claimed = ctx.principal?.id ?? (typeof ctx.metadata?.sender === 'string' ? ctx.metadata.sender : undefined);
    // issuer and authenticator together name where the id came from (channels set authenticator).
    const via = ctx.principal?.issuer ?? ctx.principal?.authenticator ?? 'inbox';
    return claimed === undefined ? 'shared' : `sender:${via}:${claimed}`;
  },
  provider,
});

import { defineSchedule } from '@lousho/build-ai-agent';

/**
 * The kit's batch intake: every 15 minutes the agent sweeps the inbox for
 * anything that arrived out-of-band (the channel triages webhooks live; this
 * catches mail dropped into inbox.json by a sync job, an importer, a human).
 */
export default defineSchedule({
  name: 'poll-inbox',
  cron: '*/15 * * * *',
  prompt: [
    'Check the inbox for new messages with list_messages (status "new").',
    'For each one: read_message, then classify_message as urgent / reply-needed / fyi / spam.',
    'Before drafting for a sender, recall_senders for what you know about them.',
    'For urgent and reply-needed messages, draft_reply in my voice, then call send_reply once - it pauses for my review.',
    'For fyi and spam, just classify and mark_processed.',
    'remember_senders anything durable you learned about a sender, then summarise what you did.',
  ].join(' '),
});

/**
 * The read side of the triage pipeline: list and read messages, record a
 * classification, mark a message handled. `delete_message` exists so the
 * permission manifest has something real to deny - the agent.json rule
 * refuses it ("triage never deletes"), which is the kit's guardrail story.
 */
import { z } from 'zod';
import { defineTool } from '@lousho/build-ai-agent';
import { getMessage, listMessages, updateMessage, type MessageStatus } from '../lib/mailstore';

const STATUS = z.enum(['new', 'triaged', 'replied', 'processed', 'trashed']);

const list = defineTool({
  name: 'list_messages',
  description:
    "List inbox messages, newest first: id, sender, subject, status and a short body snippet. 'status' filters; 'all' shows everything. Start triage with status 'new'.",
  input: z.object({
    status: STATUS.or(z.literal('all')).default('new').describe("Which messages to list; 'all' shows the whole inbox"),
  }),
  annotations: { readOnlyHint: true, destructiveHint: false },
  async execute({ status }) {
    const messages = await listMessages(status === 'all' ? undefined : (status as MessageStatus));
    return messages.map(({ body, ...message }) => ({ ...message, snippet: body.slice(0, 160) }));
  },
});

const read = defineTool({
  name: 'read_message',
  description: 'Read one inbox message in full (the listing only shows a snippet).',
  input: z.object({ id: z.string().describe('The message id from list_messages') }),
  annotations: { readOnlyHint: true, destructiveHint: false },
  async execute({ id }) {
    return getMessage(id);
  },
});

const classify = defineTool({
  name: 'classify_message',
  description:
    "Record the triage classification of a message: 'urgent' (time-critical, reply today), 'reply-needed' (a real person expects an answer), 'fyi' (worth reading, no reply) or 'spam' (junk). Classifying moves the message to 'triaged'.",
  input: z.object({
    id: z.string().describe('The message id from list_messages'),
    category: z.enum(['urgent', 'reply-needed', 'fyi', 'spam']),
    reason: z.string().describe('One sentence on why, kept on the message for the human reviewing the triage'),
  }),
  async execute({ id, category, reason }) {
    return updateMessage(id, { category, categoryReason: reason, status: 'triaged' });
  },
});

const markProcessed = defineTool({
  name: 'mark_processed',
  description:
    "Mark a message fully handled - read, classified and (when it needed one) replied to or deliberately not answered. Processed messages leave the 'new'/'triaged' queues.",
  input: z.object({ id: z.string().describe('The message id from list_messages') }),
  async execute({ id }) {
    return updateMessage(id, { status: 'processed' });
  },
});

const del = defineTool({
  name: 'delete_message',
  description:
    "Move a message to 'trashed'. The kit's permission rules deny this - triage never deletes; classify junk as 'spam' and mark it processed instead.",
  input: z.object({ id: z.string().describe('The message id from list_messages') }),
  annotations: { destructiveHint: true },
  async execute({ id }) {
    return updateMessage(id, { status: 'trashed' });
  },
});

export default [list, read, classify, markProcessed, del];

/**
 * The write side of the triage pipeline: drafts, then the one externally
 * visible action - `send_reply`. `send_reply` carries `needsApproval` in the
 * tool itself AND an `ask` permission rule in agent.json: either way, the run
 * pauses and a human decides before anything lands in the outbox.
 */
import { z } from 'zod';
import { defineTool } from '@lousho/build-ai-agent';
import { appendOutbox, findDraft, getMessage, listDrafts, addDraft, updateDraft, updateMessage } from '../lib/mailstore';

const list = defineTool({
  name: 'list_drafts',
  description: 'List reply drafts, optionally for one message. Use it to find the draft to pass to send_reply.',
  input: z.object({ messageId: z.string().optional().describe('Only drafts replying to this message') }),
  annotations: { readOnlyHint: true, destructiveHint: false },
  async execute({ messageId }) {
    return listDrafts(messageId);
  },
});

const draft = defineTool({
  name: 'draft_reply',
  description:
    "Write a reply draft to a message: it is saved for human review, nothing is sent. The recipient and 'Re:' subject come from the message; pass 'subject' only to override. Write the final text - no [placeholders]; a hook refuses half-written drafts at send time.",
  input: z.object({
    messageId: z.string().describe('The message id being replied to'),
    body: z.string().describe('The full reply body, ready to send as-is'),
    subject: z.string().optional().describe("Defaults to 'Re: <original subject>'"),
  }),
  async execute({ messageId, body, subject }) {
    const message = await getMessage(messageId);
    return addDraft({ messageId, to: message.from, subject: subject ?? `Re: ${message.subject}`, body });
  },
});

const send = defineTool({
  name: 'send_reply',
  description:
    'Send a reply: the draft (draftId) or an inline body lands in the outbox and the message is marked replied. Every call pauses for human approval - call it once, with the final text, after the human has had a chance to review the draft.',
  input: z
    .object({
      messageId: z.string().describe('The message id being replied to'),
      draftId: z.string().optional().describe('A draft from draft_reply to send as-is'),
      body: z.string().optional().describe('An inline reply body when there is no draft'),
      subject: z.string().optional().describe('Subject for an inline reply; defaults to the draft\'s or "Re: <original>"'),
    })
    .refine((args) => (args.draftId !== undefined) !== (args.body !== undefined), {
      message: "pass exactly one of 'draftId' (send the reviewed draft) or 'body' (inline reply)",
    }),
  needsApproval: true,
  annotations: { readOnlyHint: false, openWorldHint: true },
  async execute({ messageId, draftId, body, subject }) {
    const message = await getMessage(messageId);
    const draftBody = draftId === undefined ? undefined : await findDraft(draftId);
    if (draftId !== undefined && (draftBody === undefined || draftBody.messageId !== messageId)) {
      throw new Error(`no draft '${draftId}' for message '${messageId}' - call list_drafts for the current draft ids`);
    }
    if (draftBody?.status === 'sent') throw new Error(`draft '${draftId}' was already sent`);
    const entry = await appendOutbox({
      messageId,
      ...(draftId !== undefined && { draftId }),
      to: draftBody?.to ?? message.from,
      subject: subject ?? draftBody?.subject ?? `Re: ${message.subject}`,
      body: draftBody?.body ?? (body as string),
    });
    if (draftBody) await updateDraft(draftBody.id, { status: 'sent' });
    await updateMessage(messageId, { status: 'replied' });
    return { sent: true, outboxId: entry.id, to: entry.to, subject: entry.subject };
  },
});

export default [list, draft, send];
